makeMtLab(document.getElementById("lab-l17"),{id:"l17",scenarios:[{"label": "Ví dụ: Dựng cây AMTS-Pack", "note": "Mỗi nút có đúng một cha.", "steps": [{"t": "Nhà máy và khu vực", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>HCM<\/b><small>nhà máy<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>PK<\/b><small>khu đóng gói<\/small><\/div><\/div>"}, {"t": "Dây chuyền", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>HCM<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>PK<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>L1<\/b><small>dây chuyền<\/small><\/div><\/div>"}, {"t": "Ba máy", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">·<\/span><div class=\"mt-box\"><b>M1<\/b><small>rót<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">·<\/span><div class=\"mt-box\"><b>M2<\/b><small>dán nắp<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">·<\/span><div class=\"mt-box\"><b>M3<\/b><small>cân<\/small><\/div><\/div>", "ask": {"q": "L1-M3 có mấy cha trực tiếp?", "o": ["0", "1", "3"], "a": 1}}]}, {"label": "Ví dụ: Sản lượng dây chuyền", "note": "Lấy ở máy cuối, không cộng các máy.", "steps": [{"t": "Số đạt từng máy", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Máy<\/th><th scope=\"col\">Số đếm<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td>10 512<\/td><\/tr><tr><td>M2<\/td><td>10 505<\/td><\/tr><tr><td>M3 (đạt)<\/td><td>10 200<\/td><\/tr><\/tbody><\/table>"}, {"t": "Sản lượng L1", "html": "<p class=\"mt-calc\">= số đạt ở M3 = <b>10 200<\/b><\/p>", "ask": {"q": "Sản lượng dây chuyền L1?", "o": ["31 217", "10 512", "10 200"], "a": 2}}]}, {"label": "Ví dụ: Thêm dây chuyền L2", "note": "Chỉ thêm dòng dữ liệu, không sửa mã.", "steps": [{"t": "INSERT dây chuyền", "html": "<p class=\"mt-calc\">line: ('L2', 'PK', 'Dây chuyền 2')<\/p>"}, {"t": "INSERT máy", "html": "<p class=\"mt-calc\">machine: ('L2-M1', 'L2', …)<\/p>", "say": "<p>Cây mới có ngay trong báo cáo khu vực PK.<\/p>"}]}, {"label": "Bẫy: Cộng số đếm mọi máy", "note": "Một hộp đi qua ba máy.", "steps": [{"t": "Cộng 10 512 + 10 505 + 10 200", "html": "<p class=\"mt-calc\">= 31 217 hộp?<\/p>"}, {"t": "Sai gấp ba lần", "html": "<p class=\"mt-calc\">Sản lượng là số hộp rời dây chuyền, không phải số lần qua máy<\/p>"}]}, {"label": "Lỗi: Máy có hai cha", "note": "Ghi M3 thuộc cả L1 và L2.", "steps": [{"t": "Dữ liệu sai", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Máy<\/th><th scope=\"col\">Dây chuyền<\/th><\/tr><\/thead><tbody><tr><td>L1-M3<\/td><td>L1<\/td><\/tr><tr><td>L1-M3<\/td><td class=\"bad\">L2<\/td><\/tr><\/tbody><\/table>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">machine_id là khóa chính → một máy một dây chuyền<\/p>", "say": "<p>Nếu máy dùng chung, mô hình hóa bằng bảng phân công theo thời gian, không phải hai cha.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l17"),"l17",[{"kind": "num", "t": "Cây thiết bị", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Nhà máy có 2 khu vực, mỗi khu 3 dây chuyền, mỗi dây chuyền 3 máy. Bao nhiêu máy?", "a": 18, "unit": "máy"}, {"q": "Cây trên có bao nhiêu nút tất cả (kể cả nhà máy)?", "a": 27, "unit": "nút"}, {"q": "M1, M2, M3 đếm 7 230, 7 228, 7 100 (M3 là số đạt). Sản lượng dây chuyền?", "a": 7100, "unit": "hộp"}], "hints": ["Nhân số con qua từng cấp.", "Sản lượng lấy ở máy cuối."], "why": "2 × 3 × 3 = 18; 1 + 2 + 6 + 18 = 27; sản lượng = 7 100."}, {"kind": "pick", "t": "Cấp nào?", "d": "<p>Xếp vào cấp ISA-95.<\/p>", "cats": ["Nhà máy", "Khu vực", "Dây chuyền", "Trạm, máy"], "items": [{"q": "HCM", "a": 0}, {"q": "Khu đóng gói PK", "a": 1}, {"q": "L1", "a": 2}, {"q": "Máy cân M3", "a": 3}, {"q": "Khu rang", "a": 1}], "hints": ["Khu vực nằm giữa nhà máy và dây chuyền.", "Máy là cấp thấp nhất trong bài."], "why": "HCM: nhà máy; PK, khu rang: khu vực; L1: dây chuyền; M3: máy."}, {"kind": "order", "t": "Từ trên xuống", "d": "<p>Sắp xếp các cấp.<\/p>", "items": ["Doanh nghiệp", "Nhà máy", "Khu vực", "Dây chuyền", "Trạm, máy"], "hints": ["Doanh nghiệp là cấp cao nhất.", "Máy là cấp thấp nhất trong bài."], "why": "Doanh nghiệp → nhà máy → khu vực → dây chuyền → máy."}]);
mesSim(document.getElementById("sim-l17"),Object.assign({id:"l17"},{kind:"db",title:"Cây thiết bị trong PostgreSQL",sub:"Mỗi cấp một bảng, khóa ngoại trỏ về cấp cha. Gõ SQL rồi Ctrl+Enter.",show:"machine",
 tables:[{name:"site",cols:[{n:"site_id",ty:"text",pk:1},{n:"name",ty:"text",nn:1}],rows:[{site_id:"HCM",name:"Nhà máy HCM"}]},
 {name:"area",cols:[{n:"area_id",ty:"text",pk:1},{n:"site_id",ty:"text",nn:1,fk:"site:site_id"},{n:"name",ty:"text",nn:1}],rows:[{area_id:"PK",site_id:"HCM",name:"Khu đóng gói"}]},
 {name:"line",cols:[{n:"line_id",ty:"text",pk:1},{n:"area_id",ty:"text",nn:1,fk:"area:area_id"},{n:"name",ty:"text",nn:1}],rows:[{line_id:"L1",area_id:"PK",name:"Dây chuyền 1"}]},
 {name:"machine",cols:[{n:"machine_id",ty:"text",pk:1},{n:"line_id",ty:"text",nn:1,fk:"line:line_id"},{n:"name",ty:"text",nn:1},{n:"is_last",ty:"boolean"}],
  rows:[{machine_id:"L1-M1",line_id:"L1",name:"Máy rót",is_last:false},{machine_id:"L1-M2",line_id:"L1",name:"Máy dán nắp",is_last:false},{machine_id:"L1-M3",line_id:"L1",name:"Máy cân",is_last:true}]},
 {name:"shift_count",cols:[{n:"machine_id",ty:"text",fk:"machine:machine_id"},{n:"good",ty:"int"}],rows:[{machine_id:"L1-M1",good:10512},{machine_id:"L1-M2",good:10505},{machine_id:"L1-M3",good:10200}]}],
 sql:"SELECT m.machine_id, m.name, l.line_id, a.area_id\nFROM machine m JOIN line l ON l.line_id = m.line_id\nJOIN area a ON a.area_id = l.area_id;",
 samples:[{l:"Thêm L2",sql:"INSERT INTO line VALUES ('L2', 'PK', 'Dây chuyền 2');"},{l:"Máy của dây chuyền chưa có",sql:"INSERT INTO machine VALUES ('L9-M1', 'L9', 'Máy rót', false);"},
  {l:"Cộng ba máy (sai)",sql:"SELECT sum(good) FROM shift_count;"},{l:"Sản lượng L1 (đúng)",sql:"SELECT m.line_id, sum(c.good) AS san_luong\nFROM shift_count c JOIN machine m ON m.machine_id = c.machine_id\nWHERE m.is_last\nGROUP BY m.line_id;"}],
 tasks:[{t:"Chạy câu truy vấn có sẵn: mỗi máy thuộc dây chuyền và khu vực nào?",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.length===3&&e.cols.includes("area_id"))},
  {t:"Thêm dây chuyền L2 vào khu PK, rồi thêm máy L2-M1 cho L2.",hint:"INSERT INTO line …; INSERT INTO machine VALUES ('L2-M1', 'L2', 'Máy rót', false);",ok:"Thêm dây chuyền là thêm dòng, không sửa mã.",check:s=>s.rows("machine").some(r=>r.line_id==="L2")},
  {t:"Thử thêm máy cho dây chuyền L9 không tồn tại. Đọc thông báo lỗi.",ok:"Khóa ngoại chặn máy “mồ côi”: mỗi thiết bị phải có đúng một cha có thật.",check:(s,c)=>c.has("sql",e=>!e.ok&&/foreign key/.test(e.err))},
  {t:"Tính sản lượng L1 đúng cách (chỉ máy cuối), so với cộng cả ba máy.",hint:"Dùng câu mẫu “Sản lượng L1 (đúng)”.",ok:"10 200, không phải 31 217: một hộp đi qua cả ba máy.",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.some(r=>r.includes(10200)))}]}));

